# Simple market simulation: buyers try to purchase from sellers who can meet their
# maximum willing price. Each successful trade splits the difference between the
# buyer's max price and the seller's minimum acceptable price, and we track the
# total surplus generated by the transactions.

buyers = [
    {"name": "Jane", "max_price": 15},
    {"name": "John", "max_price": 15},
]

sellers = [
    {"name": "Bob", "min_price": 11},
    {"name": "Alice", "min_price": 9},
]

# Keep a copy of sellers so we can remove matched sellers as trades happen.
# Sorting by minimum price helps find the cheapest available seller first.
remaining_sellers = sellers.copy()
remaining_sellers.sort(key=lambda seller: seller["min_price"])  # sort sellers by min_price

trades = []
total_surplus = 0

# Try to match each buyer with an available seller.
for buyer in buyers:
    trade_found = False

    # Look through the remaining sellers to find one that can produce a valid trade.
    for seller in remaining_sellers:
        if buyer["max_price"] >= seller["min_price"]:
            # The transaction price is the midpoint between what the buyer is willing
            # to pay and what the seller requires, creating a fair split of surplus.
            trade_price = (buyer["max_price"] + seller["min_price"]) / 2
            print(
                f'{buyer["name"]} buys from {seller["name"]} '
                f'at {trade_price}.'
            )

            # Surplus is the extra value captured by both sides of the transaction.
            buyer_surplus = buyer["max_price"] - trade_price
            seller_surplus = trade_price - seller["min_price"]
            total_surplus += buyer_surplus + seller_surplus

            print(f' Buyer surplus: {buyer_surplus}, Seller surplus: {seller_surplus}')
            trades.append((buyer["name"], seller["name"], trade_price))

            # Remove the seller after matching so they are not reused.
            remaining_sellers.remove(seller)
            trade_found = True
            break

    if not trade_found:
        print(f'{buyer["name"]} could not find a seller.')

# Summary section: report every trade and the total trade count/surplus created.
print("\nTrade summary:")
for buyer_name, seller_name, price in trades:
    print(f"{buyer_name} bought from {seller_name} for {price}.")

print(f"Total trades: {len(trades)}")
print(f"Total surplus: {total_surplus}")